                <DC.Icon w={26} h={26} viewBox={"0 0 24 24"} fill={"none"} stroke={"currentColor"} strokeWidth={"2.6"} strokeLinecap={"round"} strokeLinejoin={"round"}><SVG.Path d={"M20 12H5M11 6l-6 6 6 6"} /></DC.Icon>
